import { faker } from '@faker-js/faker'
import { v5 as uuidv5 } from 'uuid'
import { DEMO_NS, FAKER_SEED } from './constants'

faker.seed(FAKER_SEED)

export { faker }

// Deterministic uuid from a scope + name, bound to the demo namespace.
// Same name always produces the same uuid.
export function detId(scope: string, name: string | number): string {
  return uuidv5(`${scope}:${String(name)}`, DEMO_NS)
}

export function resetFaker(): void {
  faker.seed(FAKER_SEED)
}

export function pick<T>(arr: readonly T[]): T {
  return arr[Math.floor(faker.number.float({ min: 0, max: arr.length - 0.0001 }))]!
}

export function weighted<T>(entries: Array<[T, number]>): T {
  const total = entries.reduce((a, [, w]) => a + w, 0)
  let r = faker.number.float({ min: 0, max: total })
  for (const [v, w] of entries) {
    r -= w
    if (r <= 0) return v
  }
  return entries[entries.length - 1]![0]
}

// Random date between two anchors, uniform.
export function randDate(start: Date, end: Date): Date {
  const t = faker.number.int({ min: start.getTime(), max: end.getTime() })
  return new Date(t)
}

