import type { AdminClient } from '../client'
import type { DemoContext } from '../context'
import { DEMO_PASSWORD, DEMO_USER_LIST, DEMO_USERS } from '../constants'
import { detId } from '../rng'
import { log } from '../log'

const RUST = '#B23A2B'
const ONYX = '#0F0F0F'
const STONE = '#787774'
const BONE = '#F7F7F5'

const ARTIST_KEYS = ['artist1', 'artist2', 'artist3', 'guest'] as const

export async function seed(sb: AdminClient, ctx: DemoContext): Promise<void> {
  // 1. Auth users — create or update each of 7 accounts with fixed ids
  let created = 0
  for (const u of DEMO_USER_LIST) {
    const { error } = await sb.auth.admin.createUser({
      email: u.email,
      password: DEMO_PASSWORD,
      email_confirm: true,
      user_metadata: { full_name: u.fullName, demo: true },
      // Supabase admin.createUser accepts optional id on recent versions; if it 422s we fall through to update
      // @ts-expect-error — id is supported in admin.createUser for service-role
      id: u.id,
    })
    if (error) {
      // Already exists → update password + confirm
      const { error: upErr } = await sb.auth.admin.updateUserById(u.id, {
        password: DEMO_PASSWORD,
        email_confirm: true,
        user_metadata: { full_name: u.fullName, demo: true },
      })
      if (upErr && !/not.*found/i.test(upErr.message)) {
        // createUser didn't use our id → look up by email, then update
        const { data: list } = await sb.auth.admin.listUsers({ page: 1, perPage: 200 })
        const existing = list.users.find((x) => x.email?.toLowerCase() === u.email.toLowerCase())
        if (!existing) throw new Error(`[members] cannot provision ${u.email}: ${error.message} / ${upErr.message}`)
        // id mismatch — this seed requires fixed ids. Patch by updating by found id.
        // NOTE: cannot change a user's uuid; if mismatch, re-create.
        if (existing.id !== u.id) {
          await sb.auth.admin.deleteUser(existing.id)
          const { error: retryErr } = await sb.auth.admin.createUser({
            email: u.email,
            password: DEMO_PASSWORD,
            email_confirm: true,
            user_metadata: { full_name: u.fullName, demo: true },
            // @ts-expect-error — id
            id: u.id,
          })
          if (retryErr) throw new Error(`[members] re-create ${u.email}: ${retryErr.message}`)
        }
      }
    } else {
      created++
    }
    ctx.users[u.email] = u.id
  }
  log.module('members', DEMO_USER_LIST.length, `auth.users (${created} new)`)

  // 2. Profiles — handle_new_user trigger should have created rows, but upsert to fix display_name drift.
  //    Owner gets is_platform_admin so /admin is reachable.
  const { error: profErr } = await sb.from('profiles').upsert(
    DEMO_USER_LIST.map((u) => ({
      id: u.id,
      email: u.email,
      full_name: u.fullName,
      avatar_url: null,
      is_platform_admin: u.email === DEMO_USERS.owner.email,
    })),
    { onConflict: 'id' },
  )
  if (profErr) throw new Error(`[members] profiles upsert: ${profErr.message}`)
  log.module('members', DEMO_USER_LIST.length, 'profiles')

  // 3. Studio members — link each user to the demo studio with role
  const { error: memErr } = await sb.from('studio_members').upsert(
    DEMO_USER_LIST.map((u) => ({
      id: detId('studio_member', u.email),
      studio_id: ctx.studioId,
      user_id: u.id,
      role: u.role,
      joined_at: new Date(Date.now() - 90 * 86400_000).toISOString(),
      last_active_at: new Date().toISOString(),
    })),
    { onConflict: 'id' },
  )
  if (memErr) throw new Error(`[members] studio_members upsert: ${memErr.message}`)
  log.module('members', DEMO_USER_LIST.length, 'studio_members')

  // 4. Artists — 3 residents + 1 guest (4 total). Each links to a profile.
  const artistRows = ARTIST_KEYS.map((key, i) => {
    const user = DEMO_USERS[key]!
    return {
      id: detId('artist', key),
      studio_id: ctx.studioId,
      profile_id: user.id,
      display_name: user.fullName,
      bio: `${user.fullName} — demo artist for the InkOS playground.`,
      specialties: pickSpecialties(key),
      commission_default_pct: 60,
      status: key === 'guest' ? ('on_leave' as const) : ('active' as const),
      sort_order: i,
      calendar_color: [RUST, ONYX, STONE, BONE][i] ?? ONYX,
      hourly_rate_cents: 18000,
      accepts_walk_ins: key === 'artist3',
      max_bookings_per_day: 5,
      profile_bio_public: 'Years of clean-lines, color, and black-and-grey work.',
      languages_spoken: ['en'],
      social_instagram: `${user.fullName.split(' ')[0]!.toLowerCase()}.ink`,
    }
  })
  const { error: artErr } = await sb.from('artists').upsert(artistRows, { onConflict: 'id' })
  if (artErr) throw new Error(`[members] artists upsert: ${artErr.message}`)
  log.module('members', artistRows.length, 'artists')
  ctx.artistIds = artistRows.map((r) => r.id)
  ctx.guestArtistId = detId('artist', 'guest')

  // 5. Location assignments — artists primary at DT, some secondary at Mission
  const assignments: Array<{ id: string; studio_id: string; location_id: string; artist_id: string; is_primary: boolean }> = []
  artistRows.forEach((a, i) => {
    assignments.push({
