      sort_order: i,
      calendar_color: [RUST, ONYX, STONE, BONE][i] ?? ONYX,
      hourly_rate_cents: 18000,
      accepts_walk_ins: key === 'artist3',
      max_bookings_per_day: 5,
      profile_bio_public: 'Years of clean-lines, color, and black-and-grey work.',
      languages_spoken: ['en'],
      social_instagram: `${user.fullName.split(' ')[0]!.toLowerCase()}.ink`,
    }
  })
  const { error: artErr } = await sb.from('artists').upsert(artistRows, { onConflict: 'id' })
  if (artErr) throw new Error(`[members] artists upsert: ${artErr.message}`)
  log.module('members', artistRows.length, 'artists')
  ctx.artistIds = artistRows.map((r) => r.id)
  ctx.guestArtistId = detId('artist', 'guest')

  // 5. Location assignments — artists primary at DT, some secondary at Mission
  const assignments: Array<{ id: string; studio_id: string; location_id: string; artist_id: string; is_primary: boolean }> = []
  artistRows.forEach((a, i) => {
    assignments.push({
      id: detId('loc_assign', `${a.id}:primary`),
      studio_id: ctx.studioId,
      location_id: ctx.locations.primary,
      artist_id: a.id,
      is_primary: true,
    })
    if (i % 2 === 0) {
      assignments.push({
        id: detId('loc_assign', `${a.id}:secondary`),
        studio_id: ctx.studioId,
        location_id: ctx.locations.secondary,
        artist_id: a.id,
        is_primary: false,
      })
    }
  })
  const { error: laErr } = await sb.from('location_assignments').upsert(assignments, { onConflict: 'id' })
  if (laErr) throw new Error(`[members] location_assignments upsert: ${laErr.message}`)
  log.module('members', assignments.length, 'location_assignments')

  // 6. Artist schedules — weekly recurring Mon-Sat
  const scheduleRows = artistRows.flatMap((a) =>
    [1, 2, 3, 4, 5, 6].map((dow) => ({
      id: detId('schedule', `${a.id}:${dow}`),
      studio_id: ctx.studioId,
      artist_id: a.id,
      location_id: ctx.locations.primary,
      day_of_week: dow,
      start_time: '11:00',
      end_time: '20:00',
      effective_from: new Date(Date.now() - 180 * 86400_000).toISOString().slice(0, 10),
    })),
  )
  const { error: schErr } = await sb.from('artist_schedules').upsert(scheduleRows, { onConflict: 'id' })
  if (schErr) throw new Error(`[members] artist_schedules upsert: ${schErr.message}`)
  log.module('members', scheduleRows.length, 'artist_schedules')

  // 7. Artist goals — current month revenue + bookings goals per active artist
  const periodStart = new Date()
  periodStart.setDate(1)
  const periodEnd = new Date(periodStart.getFullYear(), periodStart.getMonth() + 1, 1)
  const goalRows = artistRows
    .filter((a) => a.status === 'active')
    .flatMap((a) => [
      {
        id: detId('goal', `${a.id}:revenue:${periodStart.toISOString().slice(0, 7)}`),
        studio_id: ctx.studioId,
        artist_id: a.id,
        period_type: 'month' as const,
        period_start: periodStart.toISOString().slice(0, 10),
        period_end: periodEnd.toISOString().slice(0, 10),
        metric: 'revenue' as const,
        target_value: 12000,
        current_value: 6400 + Math.floor(Math.random() * 3000),
      },
      {
        id: detId('goal', `${a.id}:bookings:${periodStart.toISOString().slice(0, 7)}`),
        studio_id: ctx.studioId,
        artist_id: a.id,
        period_type: 'month' as const,
        period_start: periodStart.toISOString().slice(0, 10),
        period_end: periodEnd.toISOString().slice(0, 10),
        metric: 'bookings' as const,
        target_value: 40,
        current_value: 18,
      },
    ])
  const { error: goalErr } = await sb.from('artist_goals').upsert(goalRows, { onConflict: 'id' })
  if (goalErr) throw new Error(`[members] artist_goals upsert: ${goalErr.message}`)
  log.module('members', goalRows.length, 'artist_goals')

  // 8. Guest artist engagement
  const guestArtist = artistRows.find((a) => a.id === ctx.guestArtistId)!
  const start = new Date(Date.now() - 14 * 86400_000)
  const end = new Date(Date.now() + 14 * 86400_000)
  const { error: gErr } = await sb.from('guest_artist_engagements').upsert(
    {
      id: detId('guest_engagement', guestArtist.id),
      studio_id: ctx.studioId,
      artist_id: guestArtist.id,
      status: 'active' as const,
      start_date: start.toISOString().slice(0, 10),
      end_date: end.toISOString().slice(0, 10),
      split_pct_studio: 30,
      split_pct_artist: 70,
      studio_provides: ['chair', 'consumables', 'front_desk'],
      agreement_notes: 'Four-week residency, Mumbai → SF. Walk-ins welcome.',
      contact_email: DEMO_USERS.guest.email,
      contact_phone: '+1 415 555 0999',
      show_on_booking_page: true,
      calendar_color: RUST,
    },
    { onConflict: 'id' },
  )
  if (gErr) throw new Error(`[members] guest_artist_engagements upsert: ${gErr.message}`)
  log.module('members', 1, 'guest_artist_engagements')

  // 9. Artist tax info — W-9 on file for 3 residents (no tin data, just metadata)
  const taxRows = artistRows
    .filter((a) => a.status === 'active')
    .map((a, i) => ({
      id: detId('artist_tax', a.id),
