import type { AdminClient } from '../client'
import type { DemoContext } from '../context'
import { detId } from '../rng'
import { log } from '../log'
import { DEMO_USERS } from '../constants'

export async function seed(sb: AdminClient, ctx: DemoContext): Promise<void> {
  // 1. Commission rules — one default per artist, 60% of service, 100% tip split
  const ruleRows = ctx.artistIds.map((artistId, i) => ({
    id: detId('commission_rule', `${artistId}:default`),
    studio_id: ctx.studioId,
    artist_id: artistId,
    service_id: null,
    percentage: 60,
    flat_fee_cents: null,
    tip_split_pct: 100,
    priority: i,
    effective_from: new Date(Date.now() - 180 * 86400_000).toISOString().slice(0, 10),
    created_by: DEMO_USERS.owner.id,
  }))
  const { error: rErr } = await sb.from('commission_rules').upsert(ruleRows, { onConflict: 'id' })
  if (rErr) throw new Error(`[payroll] commission_rules upsert: ${rErr.message}`)
  log.module('payroll', ruleRows.length, 'commission_rules')

  // 2. Commission records — derive from completed bookings
  const { data: completed } = await sb
    .from('bookings')
    .select('id, artist_id, service_id, price_cents, tip_cents, scheduled_at')
    .eq('studio_id', ctx.studioId)
    .eq('status', 'completed')
    .in('id', ctx.completedBookingIds.length > 0 ? ctx.completedBookingIds : ['never'])

  const commRecords = (completed ?? []).map((b, i) => {
    const commission = Math.floor((b.price_cents ?? 0) * 0.6)
    const tipComm = b.tip_cents ?? 0
    return {
      id: detId('commission_record', b.id),
      studio_id: ctx.studioId,
      booking_id: b.id,
      artist_id: b.artist_id,
      rule_id: detId('commission_rule', `${b.artist_id}:default`),
      rule_snapshot: { percentage: 60, tip_split_pct: 100 } as unknown as object,
      service_id: b.service_id,
      service_price_cents: b.price_cents ?? 0,
      tip_cents: tipComm,
      commission_cents: commission,
      tip_commission_cents: tipComm,
      status: i === 0 ? ('disputed' as const) : ('approved' as const),
      approved_by: DEMO_USERS.owner.id,
      approved_at: new Date(Date.now() - 7 * 86400_000).toISOString(),
    }
  })
  for (let i = 0; i < commRecords.length; i += 100) {
    const chunk = commRecords.slice(i, i + 100)
    if (!chunk.length) continue
    const { error } = await sb.from('commission_records').upsert(chunk, { onConflict: 'id' })
    if (error) throw new Error(`[payroll] commission_records upsert chunk ${i}: ${error.message}`)
  }
  log.module('payroll', commRecords.length, 'commission_records')

  // 3. Commission adjustments — 2 bonuses, 1 penalty, 1 correction
  const adjRows = ctx.artistIds.slice(0, 3).map((artistId, i) => {
    const kinds = ['bonus', 'correction', 'penalty'] as const
    return {
      id: detId('commission_adj', `${artistId}:${i}`),
      studio_id: ctx.studioId,
      artist_id: artistId,
      amount_cents: i === 2 ? -5000 : 10000,
      kind: kinds[i]!,
      reason: i === 0
        ? 'Q2 performance bonus'
        : i === 1
        ? 'Correction: missed commission on 4/10 session'
        : 'No-show chargeback',
      applied_at: new Date(Date.now() - (14 - i * 2) * 86400_000).toISOString(),
      status: 'approved' as const,
      created_by: DEMO_USERS.owner.id,
      approved_by: DEMO_USERS.owner.id,
      approved_at: new Date(Date.now() - (10 - i * 2) * 86400_000).toISOString(),
      metadata: { demo: true } as unknown as object,
    }
  })
  const { error: adjErr } = await sb.from('commission_adjustments').upsert(adjRows, { onConflict: 'id' })
  if (adjErr) throw new Error(`[payroll] commission_adjustments upsert: ${adjErr.message}`)
  log.module('payroll', adjRows.length, 'commission_adjustments')

  // 4. Commission disputes — one per first disputed record
  if (commRecords.length > 0) {
    const disputedRecord = commRecords[0]!
    const { error: dErr } = await sb.from('commission_disputes').upsert(
      {
        id: detId('commission_dispute', disputedRecord.id),
        studio_id: ctx.studioId,
        commission_record_id: disputedRecord.id,
        raised_by: DEMO_USERS.artist1.id,
        reason: 'Price charged was not what I quoted',
        status: 'open' as const,
      },
      { onConflict: 'id' },
    )
    if (dErr) throw new Error(`[payroll] commission_disputes upsert: ${dErr.message}`)
    log.module('payroll', 1, 'commission_disputes')
  }

  // 5. Payroll runs — 3 past periods
  const now = new Date()
  const runRows = Array.from({ length: 3 }, (_, i) => {
    const periodStart = new Date(now.getFullYear(), now.getMonth() - (i + 1), 1)
    const periodEnd = new Date(now.getFullYear(), now.getMonth() - i, 0)
    return {
      id: detId('payroll_run', `${i}`),
      studio_id: ctx.studioId,
      period_start: periodStart.toISOString().slice(0, 10),
      period_end: periodEnd.toISOString().slice(0, 10),
      status: 'paid' as const,
      label: `Period ${periodStart.toISOString().slice(0, 7)}`,
      total_gross_cents: 180000 + i * 20000,
      total_commission_cents: 108000 + i * 12000,
      total_tips_cents: 12000 + i * 1500,
      total_adjustments_cents: i === 0 ? 10000 : 0,
      total_net_cents: 130000 + i * 13500,
      artist_count: ctx.artistIds.filter((_, ai) => ai < 3).length,
      record_count: 8 + i * 2,
      calculated_at: new Date(periodEnd.getTime() + 1 * 86400_000).toISOString(),
      calculated_by: DEMO_USERS.owner.id,
      approved_at: new Date(periodEnd.getTime() + 2 * 86400_000).toISOString(),
      approved_by: DEMO_USERS.owner.id,
      paid_at: new Date(periodEnd.getTime() + 3 * 86400_000).toISOString(),
      paid_by: DEMO_USERS.owner.id,
      payment_method: 'ach' as const,
      payment_reference: `batch_${i}`,
    }
  })
  const { error: prErr } = await sb.from('payroll_runs').upsert(runRows, { onConflict: 'id' })
  if (prErr) throw new Error(`[payroll] payroll_runs upsert: ${prErr.message}`)
  log.module('payroll', runRows.length, 'payroll_runs')

  // 6. Payroll artist summary — one row per artist per run
  const summaryRows = runRows.flatMap((run) =>
    ctx.artistIds.slice(0, 3).map((artistId, idx) => {
      const commissionTotal = 35000 + idx * 5000
      const tipTotal = 4000 + idx * 500
      const grossTotal = commissionTotal + tipTotal
      return {
        id: detId('payroll_summary', `${run.id}:${artistId}`),
        studio_id: ctx.studioId,
        payroll_run_id: run.id,
        artist_id: artistId,
        artist_name_snapshot: `Artist ${idx + 1}`,
        commission_count: 8 + idx,
        commission_total_cents: commissionTotal,
        tip_total_cents: tipTotal,
        adjustment_count: 0,
        adjustment_total_cents: 0,
        gross_total_cents: grossTotal,
        deductions_cents: 0,
        net_total_cents: grossTotal,
        payment_method: 'ach' as const,
        payment_reference: `sum_${run.id}_${artistId}`.slice(0, 50),
        paid_at: run.paid_at,
        status: 'paid' as const,
      }
    }),
  )
  const { error: psErr } = await sb.from('payroll_artist_summary').upsert(summaryRows, { onConflict: 'id' })
  if (psErr) throw new Error(`[payroll] payroll_artist_summary upsert: ${psErr.message}`)
  log.module('payroll', summaryRows.length, 'payroll_artist_summary')

  // 7. Payroll payment batches — one per payroll run
  const batchRows = runRows.map((run, i) => ({
    id: detId('payroll_batch', run.id),
    studio_id: ctx.studioId,
    payroll_run_id: run.id,
    method: 'ach' as const,
    batch_reference: `ACH-${run.period_start}`,
    total_amount_cents: run.total_net_cents ?? 0,
    artist_count: 3,
    processed_at: run.paid_at ?? new Date().toISOString(),
    processed_by: DEMO_USERS.owner.id,
    status: 'settled' as const,
    settled_at: new Date(new Date(run.paid_at ?? Date.now()).getTime() + 2 * 86400_000).toISOString(),
    metadata: { demo: true, batch_idx: i } as unknown as object,
  }))
  const { error: batchErr } = await sb.from('payroll_payment_batches').upsert(batchRows, { onConflict: 'id' })
  if (batchErr) throw new Error(`[payroll] payroll_payment_batches upsert: ${batchErr.message}`)
  log.module('payroll', batchRows.length, 'payroll_payment_batches')

  // 8. Tax forms — 1099-K for each resident artist for last year
  const taxYear = now.getFullYear() - 1
  const taxRows = ctx.artistIds.slice(0, 3).map((artistId, i) => ({
    id: detId('tax_form', `${artistId}:${taxYear}`),
    studio_id: ctx.studioId,
    artist_id: artistId,
    tax_year: taxYear,
    form_type: '1099-K' as const,
    status: 'sent' as const,
    gross_amount_cents: 4200000 + i * 500000,
    transaction_count: 180 + i * 30,
    threshold_met: true,
    pdf_storage_path: `tax-forms/demo/1099-K-${artistId}-${taxYear}.pdf`,
    sent_at: new Date(`${taxYear}-02-15T10:00:00Z`).toISOString(),
    sent_to_email: `artist${i + 1}@demo.inkos.test`,
    generated_at: new Date(`${taxYear}-02-10T10:00:00Z`).toISOString(),
    generated_by: DEMO_USERS.owner.id,
    locked_at: new Date(`${taxYear}-02-15T10:00:00Z`).toISOString(),
  }))
  const { error: txErr } = await sb.from('tax_forms').upsert(taxRows, { onConflict: 'id' })
  if (txErr) throw new Error(`[payroll] tax_forms upsert: ${txErr.message}`)
  log.module('payroll', taxRows.length, 'tax_forms')
}

