import type { AdminClient } from '../client'
import type { DemoContext } from '../context'
import { detId, faker } from '../rng'
import { log } from '../log'
import { DEMO_USERS } from '../constants'

const STYLE_CATS = ['blackwork', 'neo_trad', 'realism', 'geometric', 'minimalist', 'japanese', 'illustrative'] as const

export async function seed(sb: AdminClient, ctx: DemoContext): Promise<void> {
  // 1. AI design templates (studio-scoped)
  const tmplRows = STYLE_CATS.slice(0, 5).map((cat, i) => ({
    id: detId('ai_template', cat),
    studio_id: ctx.studioId,
    name: `${cat.replace('_', ' ')} starter`,
    style_category: cat,
    system_prompt: `You are a senior tattoo artist specializing in ${cat} style. Generate conceptual designs with placement advice.`,
    user_prompt_template: 'Design a {{size}} {{body_area}} piece in {{style}} style. {{description}}',
    image_prompt_template: '{{description}}, {{style}} style, tattoo illustration, black ink on skin',
    is_active: true,
    is_default: i === 0,
    usage_count: faker.number.int({ min: 5, max: 40 }),
    avg_rating: 4 + Math.random(),
  }))
  const { error: tErr } = await sb.from('ai_design_templates').upsert(tmplRows, { onConflict: 'id' })
  if (tErr) throw new Error(`[ai] ai_design_templates upsert: ${tErr.message}`)
  log.module('ai', tmplRows.length, 'ai_design_templates')

  // 2. AI design requests — 20 spread across last 30 days
  const requestRows = Array.from({ length: 20 }, (_, i) => {
    const createdAt = new Date(Date.now() - faker.number.int({ min: 0, max: 30 }) * 86400_000)
    const status = faker.helpers.arrayElement(['completed', 'completed', 'completed', 'pending', 'processing', 'failed'] as const)
    return {
      id: detId('ai_request', `${i}`),
      studio_id: ctx.studioId,
      client_id: ctx.clientIds[i % ctx.clientIds.length]!,
      artist_id: ctx.artistIds[i % ctx.artistIds.length]!,
      style_category: faker.helpers.arrayElement(STYLE_CATS),
      body_area: faker.helpers.arrayElement(['forearm', 'upper_back', 'thigh', 'chest', 'ribcage', 'shoulder']),
      size_estimate: faker.helpers.arrayElement(['small', 'medium', 'large', 'xl']),
      budget_min_cents: 20000,
      budget_max_cents: 80000,
      description: faker.lorem.sentence({ min: 10, max: 18 }),
      mood_keywords: faker.helpers.arrayElements(['bold', 'minimal', 'mystical', 'dark', 'clean', 'organic'], 3),
      avoid_keywords: faker.helpers.arrayElements(['cartoon', 'text-heavy'], 1),
      status,
      priority: 0,
      total_tokens_used: status === 'completed' ? faker.number.int({ min: 800, max: 3000 }) : 0,
      total_cost_cents: status === 'completed' ? faker.number.int({ min: 5, max: 40 }) : 0,
      processing_started_at: status !== 'pending' ? createdAt.toISOString() : null,
      completed_at: status === 'completed' ? new Date(createdAt.getTime() + 60_000).toISOString() : null,
      failed_at: status === 'failed' ? new Date(createdAt.getTime() + 30_000).toISOString() : null,
      failure_reason: status === 'failed' ? 'Upstream rate limit' : null,
      metadata: { demo: true } as unknown as object,
      created_at: createdAt.toISOString(),
    }
  })
  const { error: rErr } = await sb.from('ai_design_requests').upsert(requestRows, { onConflict: 'id' })
  if (rErr) throw new Error(`[ai] ai_design_requests upsert: ${rErr.message}`)
  log.module('ai', requestRows.length, 'ai_design_requests')

  // 3. AI design outputs — 2-3 per completed request
  type OutRow = {
    id: string
    studio_id: string
    request_id: string
    sequence: number
    prompt_text: string
    model: string
    response_text: string
    image_url: string
    image_model: string
    tokens_input: number
    tokens_output: number
    cost_cents: number
    generation_time_ms: number
    rating: number
    status: 'pending' | 'generating' | 'completed' | 'failed' | 'rejected' | 'approved'
    approved_by: string | null
    approved_at: string | null
    shared_with_client: boolean
    metadata: object
  }
  const outputs: OutRow[] = []
  for (const req of requestRows) {
    if (req.status !== 'completed') continue
    const count = faker.number.int({ min: 2, max: 3 })
    for (let j = 0; j < count; j++) {
      outputs.push({
        id: detId('ai_output', `${req.id}:${j}`),
        studio_id: ctx.studioId,
        request_id: req.id,
        sequence: j + 1,
        prompt_text: req.description,
        model: 'claude-opus-4-7',
        response_text: `Option ${j + 1}: ${faker.lorem.paragraph({ min: 3, max: 6 })}`,
        image_url: `https://demo-ai-assets.inkos.test/${req.id}/${j}.png`,
        image_model: 'stability/sdxl',
        tokens_input: 500 + j * 50,
        tokens_output: 800 + j * 100,
        cost_cents: 8 + j,
        generation_time_ms: 4200 + j * 300,
        rating: j === 0 ? 5 : 4,
        status: j === 0 ? 'approved' : 'completed',
        approved_by: j === 0 ? DEMO_USERS.artist1.id : null,
        approved_at: j === 0 ? new Date().toISOString() : null,
        shared_with_client: j === 0,
        metadata: { demo: true },
      })
    }
  }
  for (let i = 0; i < outputs.length; i += 100) {
    const chunk = outputs.slice(i, i + 100)
    const { error } = await sb.from('ai_design_outputs').upsert(chunk, { onConflict: 'id' })
    if (error) throw new Error(`[ai] ai_design_outputs upsert chunk ${i}: ${error.message}`)
  }
  log.module('ai', outputs.length, 'ai_design_outputs')

  // 4. AI usage log — 60 events across 30 days
  const logRows = Array.from({ length: 60 }, (_, i) => {
    const created = new Date(Date.now() - faker.number.int({ min: 0, max: 30 }) * 86400_000 - faker.number.int({ min: 0, max: 86400 }) * 1000)
    const provider = faker.helpers.arrayElement(['anthropic', 'anthropic', 'anthropic', 'openai', 'stability'] as const)
    return {
      studio_id: ctx.studioId,
      request_id: requestRows[i % requestRows.length]!.id,
      output_id: null,
      api_provider: provider,
      model: provider === 'anthropic' ? 'claude-opus-4-7' : provider === 'openai' ? 'gpt-4o' : 'stability-sdxl',
      endpoint: provider === 'stability' ? 'image-to-image' : 'messages',
      tokens_input: faker.number.int({ min: 300, max: 2000 }),
      tokens_output: faker.number.int({ min: 400, max: 2500 }),
      cost_cents: faker.number.int({ min: 1, max: 20 }),
      duration_ms: faker.number.int({ min: 800, max: 7500 }),
      http_status: i % 17 === 0 ? 429 : 200,
      error_message: i % 17 === 0 ? 'Rate limited' : null,
      request_metadata: { demo: true } as unknown as object,
      created_at: created.toISOString(),
    }
  })
  // ai_usage_log.id is bigint, auto — do NOT set. Use plain insert so we rely on auto-id.
  // Idempotency: delete demo rows first by a marker (metadata.demo=true + studio_id).
  await sb.from('ai_usage_log').delete().eq('studio_id', ctx.studioId).contains('request_metadata', { demo: true })
  for (let i = 0; i < logRows.length; i += 100) {
    const chunk = logRows.slice(i, i + 100)
    const { error } = await sb.from('ai_usage_log').insert(chunk)
    if (error) throw new Error(`[ai] ai_usage_log insert chunk ${i}: ${error.message}`)
  }
  log.module('ai', logRows.length, 'ai_usage_log')
}

