import type { AdminClient } from '../client'
import type { DemoContext } from '../context'
import { detId, faker } from '../rng'
import { log } from '../log'
import { DEMO_USERS } from '../constants'

export async function seed(sb: AdminClient, ctx: DemoContext): Promise<void> {
  const now = Date.now()

  // 1. Conversations — 8 threads, mixed channels + triage tags
  const channels = ['sms', 'email', 'instagram', 'sms', 'email', 'instagram', 'voice', 'sms'] as const
  const triageTags = ['inquiry', 'booking', 'client', 'rescheduling', 'pricing', 'deposit_paid', 'missed_call', 'inquiry'] as const

  const conversationRows = Array.from({ length: 8 }, (_, i) => {
    const clientId = ctx.clientIds[i]!
    const channel = channels[i]!
    return {
      id: detId('conversation', `${i}`),
      studio_id: ctx.studioId,
      client_id: clientId,
      external_identifier: channel === 'email'
        ? `client-${i}@demo.test`
        : channel === 'sms' || channel === 'voice'
          ? `+1 415 555 ${String(3000 + i).slice(-4)}`
          : `@ig_user_${i}`,
      display_name: faker.person.fullName(),
      channel,
      last_message_at: new Date(now - i * 3600_000).toISOString(),
      last_message_preview: faker.lorem.sentence({ min: 5, max: 12 }),
      last_message_direction: (i % 3 === 0 ? 'outbound' : 'inbound') as 'outbound' | 'inbound',
      assigned_to: i % 2 === 0 ? DEMO_USERS.recept1.id : DEMO_USERS.recept2.id,
      unread_count: i % 3 === 0 ? 2 : 0,
      starred: i === 0,
      triage_tag: triageTags[i]!,
    }
  })
  const { error: cErr } = await sb.from('conversations').upsert(conversationRows, { onConflict: 'id' })
  if (cErr) throw new Error(`[messaging] conversations upsert: ${cErr.message}`)
  log.module('messaging', conversationRows.length, 'conversations')
  ctx.conversationIds = conversationRows.map((r) => r.id)

  // 2. Client communications — 5 messages per conversation
  type CommRow = {
    id: string
    studio_id: string
    client_id: string
    conversation_id: string
    channel: 'email' | 'sms' | 'whatsapp' | 'in_app'
    direction: 'outbound' | 'inbound'
    subject: string | null
    body: string
    status: 'queued' | 'sent' | 'delivered' | 'opened' | 'clicked' | 'failed' | 'bounced'
    sent_at: string
    delivered_at: string | null
    metadata: object
  }
  const comms: CommRow[] = []
  conversationRows.forEach((conv, ci) => {
    for (let m = 0; m < 5; m++) {
      const direction = m % 2 === 0 ? 'inbound' : 'outbound'
      const channelKind: CommRow['channel'] = conv.channel === 'voice' ? 'sms' : conv.channel === 'instagram' || conv.channel === 'facebook' ? 'in_app' : conv.channel as CommRow['channel']
      comms.push({
        id: detId('comm', `${conv.id}:${m}`),
        studio_id: ctx.studioId,
        client_id: conv.client_id!,
        conversation_id: conv.id,
        channel: channelKind,
        direction,
        subject: channelKind === 'email' ? faker.lorem.words({ min: 3, max: 6 }) : null,
        body: faker.lorem.sentence({ min: 8, max: 20 }),
        status: 'delivered',
        sent_at: new Date(now - (ci * 5 + (4 - m)) * 3600_000).toISOString(),
        delivered_at: new Date(now - (ci * 5 + (4 - m)) * 3600_000 + 60_000).toISOString(),
        metadata: { demo: true },
      })
    }
  })
  for (let i = 0; i < comms.length; i += 100) {
    const chunk = comms.slice(i, i + 100)
    const { error } = await sb.from('client_communications').upsert(chunk, { onConflict: 'id' })
    if (error) throw new Error(`[messaging] client_communications upsert chunk ${i}: ${error.message}`)
  }
  log.module('messaging', comms.length, 'client_communications')

  // 3. Auto-reply rules — wire to message templates (slug-based ids)
  const templateInquiryId = detId('msg_template', 'inquiry-reply')
  const autoReplyRows = [
    { id: detId('auto_reply', 'new_inquiry'), studio_id: ctx.studioId, trigger_type: 'new_inquiry' as const, template_id: templateInquiryId, enabled: true, cooldown_minutes: 60, tone: 'casual' as const, keyword: null },
    { id: detId('auto_reply', 'missed_call'), studio_id: ctx.studioId, trigger_type: 'missed_call' as const, template_id: templateInquiryId, enabled: true, cooldown_minutes: 30, tone: 'casual' as const, keyword: null },
    { id: detId('auto_reply', 'deposit_paid'), studio_id: ctx.studioId, trigger_type: 'deposit_paid' as const, template_id: detId('msg_template', 'booking-confirm'), enabled: true, cooldown_minutes: 0, tone: 'casual' as const, keyword: null },
  ]
  const { error: arErr } = await sb.from('auto_reply_rules').upsert(autoReplyRows, { onConflict: 'id' })
  if (arErr) throw new Error(`[messaging] auto_reply_rules upsert: ${arErr.message}`)
  log.module('messaging', autoReplyRows.length, 'auto_reply_rules')

  // 4. Missed calls — 4
  const missedRows = Array.from({ length: 4 }, (_, i) => ({
    id: detId('missed_call', `${i}`),
    studio_id: ctx.studioId,
    caller_number: `+1 415 555 ${String(4000 + i).slice(-4)}`,
    called_at: new Date(now - (i + 1) * 3600_000 * 3).toISOString(),
    replied_at: i === 0 ? new Date(now - i * 3600_000).toISOString() : null,
  }))
  const { error: mErr } = await sb.from('missed_calls').upsert(missedRows, { onConflict: 'id' })
  if (mErr) throw new Error(`[messaging] missed_calls upsert: ${mErr.message}`)
  log.module('messaging', missedRows.length, 'missed_calls')

  // 5. Inbox assignments — track pending items from existing seeded rows
  const { data: pendingRequests } = await sb
    .from('consent_form_requests')
    .select('id')
    .eq('studio_id', ctx.studioId)
    .eq('status', 'pending')
    .limit(3)
  const { data: lowStockAlerts } = await sb
    .from('stock_alerts')
    .select('id')
    .eq('studio_id', ctx.studioId)
    .is('acknowledged_at', null)
    .limit(3)
  const { data: unpaidDeposits } = await sb
    .from('bookings')
    .select('id')
    .eq('studio_id', ctx.studioId)
    .eq('deposit_paid', false)
    .eq('status', 'pending')
    .limit(3)
  const { data: failedPayments } = await sb
    .from('payments')
    .select('id')
    .eq('studio_id', ctx.studioId)
    .eq('status', 'failed')
    .limit(3)

  const assignRows: Array<{
    id: string
    studio_id: string
    item_kind: 'deposit' | 'form' | 'waitlist' | 'client' | 'booking-conflict' | 'missed-call' | 'low-inventory' | 'failed-payment'
    item_id: string
    assigned_to: string | null
  }> = []
  ;(pendingRequests ?? []).forEach((r, i) =>
    assignRows.push({
      id: detId('inbox_assign', `form:${r.id}`),
      studio_id: ctx.studioId,
      item_kind: 'form',
      item_id: r.id,
      assigned_to: i % 2 === 0 ? DEMO_USERS.recept1.id : null,
    }),
  )
  ;(lowStockAlerts ?? []).forEach((r) =>
    assignRows.push({
      id: detId('inbox_assign', `low:${r.id}`),
      studio_id: ctx.studioId,
      item_kind: 'low-inventory',
      item_id: r.id,
      assigned_to: DEMO_USERS.owner.id,
    }),
  )
  ;(unpaidDeposits ?? []).forEach((r) =>
    assignRows.push({
      id: detId('inbox_assign', `dep:${r.id}`),
      studio_id: ctx.studioId,
      item_kind: 'deposit',
      item_id: r.id,
      assigned_to: DEMO_USERS.recept1.id,
    }),
  )
  ;(failedPayments ?? []).forEach((r) =>
    assignRows.push({
      id: detId('inbox_assign', `failed:${r.id}`),
      studio_id: ctx.studioId,
      item_kind: 'failed-payment',
      item_id: r.id,
      assigned_to: DEMO_USERS.owner.id,
    }),
  )
  missedRows.slice(0, 2).forEach((m) =>
    assignRows.push({
      id: detId('inbox_assign', `miss:${m.id}`),
      studio_id: ctx.studioId,
      item_kind: 'missed-call',
      item_id: m.id,
      assigned_to: DEMO_USERS.recept1.id,
    }),
  )
  if (assignRows.length > 0) {
    const { error } = await sb.from('inbox_assignments').upsert(assignRows, { onConflict: 'id' })
    if (error) throw new Error(`[messaging] inbox_assignments upsert: ${error.message}`)
  }
  log.module('messaging', assignRows.length, 'inbox_assignments')
}

