/**
 * Reset the demo studio: delete all rows scoped to DEMO_STUDIO_ID, delete the
 * 7 demo auth users, then run the full seed again.
 *
 * NOTE: deliberately does not `TRUNCATE` — we only delete rows owned by the
 * demo studio so shared tables (role_permissions, plans) survive.
 */
import { adminClient } from './client'
import { DEMO_STUDIO_ID, DEMO_USER_LIST } from './constants'
import { log } from './log'

// Reverse dependency order — children before parents. Tables without studio_id
// are filtered differently (by foreign key or by the demo-prefix ids).
const STUDIO_SCOPED_TABLES = [
  'inbox_assignments',
  'audit_log',
  'team_audit_log',
  'user_pinned_items',
  'referral_redemptions',
  'referral_codes',
  'marketing_campaigns',
  'flash_event_slots',
  'flash_event_designs',
  'flash_events',
  'ai_usage_log',
  'ai_design_outputs',
  'ai_design_requests',
  'ai_design_templates',
  'reach_ink_records',
  'consent_kiosk_sessions',
  'consent_auto_send_rules',
  'consent_form_requests',
  'consent_form_submissions',
  'consent_form_templates',
  'missed_calls',
  'auto_reply_rules',
  'client_communications',
  'conversations',
  'message_templates',
  'stock_alerts',
  'purchase_order_lines',
  'purchase_orders',
  'inventory_movements',
  'inventory_items',
  'studio_ink_registry',
  'suppliers',
  'tax_forms',
  'payroll_payment_batches',
  'payroll_artist_summary',
  'payroll_runs',
  'commission_disputes',
  'commission_adjustments',
  'commission_records',
  'commission_rules',
  'refund_requests',
  'invoices',
  'payments',
  'project_activity_log',
  'booking_participants',
  'booking_photos',
  'bookings',
  'projects',
  'waitlist_entries',
  'client_consent_preferences',
  'client_files',
  'client_notes',
  'clients',
  'client_tags',
  'artist_portfolio_items',
  'artist_goals',
  'artist_tax_info',
  'artist_schedules',
  'artist_blocked_dates',
  'guest_artist_engagements',
  'location_assignments',
  'artists',
  'style_tags',
  'booking_page_settings',
  'services',
  'feature_flags',
  'usage_meters',
  'domain_verifications',
  'subscriptions',
  'studio_members',
  'locations',
  'studios',
] as const

// Tables scoped by something OTHER than studio_id — delete by related foreign keys.
async function wipeCrossKeyTables(sb: ReturnType<typeof adminClient>): Promise<void> {
  // project_deposit_transactions (scoped by project_id → projects.studio_id)
  await sb
    .from('project_deposit_transactions')
    .delete()
    .in('project_id', await scopedProjectIds(sb))

  // purchase_order_lines also cross-scoped — covered in STUDIO_SCOPED_TABLES above

  // service_artists — no studio_id but service_id links back. Clean via services cascade on delete; also run explicit:
  const { data: services } = await sb.from('services').select('id').eq('studio_id', DEMO_STUDIO_ID)
  if (services && services.length > 0) {
    await sb.from('service_artists').delete().in('service_id', services.map((s) => s.id))
  }

  // webhook_events has no studio_id — clean by demo event_id prefix
  await sb.from('webhook_events').delete().like('event_id', 'evt_demo_%')

  // system_announcements has no studio_id — only delete the ones we created
  await sb.from('system_announcements').delete().eq('title', 'Welcome to the InkOS demo')
}

async function scopedProjectIds(sb: ReturnType<typeof adminClient>): Promise<string[]> {
  const { data } = await sb.from('projects').select('id').eq('studio_id', DEMO_STUDIO_ID)
  return (data ?? []).map((r) => r.id)
}

async function main(): Promise<void> {
  log.header('InkOS demo reset — wiping')
  const sb = adminClient()

  // Wipe cross-keyed tables first
  await wipeCrossKeyTables(sb)
  log.ok('cross-key tables wiped')

  // Wipe studio-scoped tables in order
  for (const table of STUDIO_SCOPED_TABLES) {
    try {
      const { error } = await sb
        .from(table)
        // Tables with `studio_id` column — filter by it
        .delete()
        .eq('studio_id', DEMO_STUDIO_ID)
      if (error && !/column "studio_id" does not exist/i.test(error.message)) {
        log.warn(`${table}: ${error.message}`)
      } else if (!error) {
        log.ok(`wiped ${table}`)
      }
    } catch (err) {
      log.warn(`${table}: ${(err as Error).message}`)
    }
  }

  // Studios — delete the demo row itself
  const { error: studioDelErr } = await sb.from('studios').delete().eq('id', DEMO_STUDIO_ID)
  if (studioDelErr) log.warn(`studios: ${studioDelErr.message}`)
  else log.ok('wiped studios')

  // Delete demo auth users
  for (const u of DEMO_USER_LIST) {
    const { error } = await sb.auth.admin.deleteUser(u.id)
    if (error && !/not.*found/i.test(error.message)) {
      log.warn(`auth user ${u.email}: ${error.message}`)
    }
  }
  log.ok('wiped demo auth users')

  // Re-seed
  log.header('re-seeding')
  const { spawn } = await import('node:child_process')
  const p = spawn('tsx', ['--env-file=.env.local', 'scripts/seed/demo/run.ts'], {
    stdio: 'inherit',
    env: process.env,
  })
  p.on('exit', (code) => process.exit(code ?? 0))
}

main().catch((err) => {
  log.err(err instanceof Error ? err.stack ?? err.message : String(err))
  process.exit(1)
})

