  log.module('payroll', batchRows.length, 'payroll_payment_batches')

  // 8. Tax forms — 1099-K for each resident artist for last year
  const taxYear = now.getFullYear() - 1
  const taxRows = ctx.artistIds.slice(0, 3).map((artistId, i) => ({
    id: detId('tax_form', `${artistId}:${taxYear}`),
