import type { ClientTag } from '@/components/clients/TagChip'

export const DEFAULT_CLIENT_TAGS = [
  { name: 'VIP', color: 'purple', icon: null },
  { name: 'New client', color: 'emerald', icon: null },
  { name: 'Walk-in', color: 'amber', icon: null },
  { name: 'Referral', color: 'pink', icon: null },
  { name: 'Consultation', color: 'cyan', icon: null },
  { name: 'Needs follow-up', color: 'red', icon: null },
  { name: 'Cover-up', color: 'gray', icon: null },
  { name: 'Allergies', color: 'red', icon: null },
] satisfies Array<Pick<ClientTag, 'name' | 'color' | 'icon'>>

export type ClientTagsSupabase = {
  from: (table: 'client_tags') => {
    select: (columns: string) => {
      eq: (column: string, value: string) => {
        order: (column: string) => Promise<{ data: ClientTag[] | null; error: unknown }>
      }
    }
    insert: (rows: Array<{
      studio_id: string
      name: string
      color: ClientTag['color']
      icon: null
    }>) => Promise<{ error: { code?: string } | null }>
  }
}

export async function ensureDefaultClientTags(
  supabase: ClientTagsSupabase,
  studioId: string,
  existingTags: ClientTag[],
): Promise<ClientTag[]> {
  const existingNames = new Set(existingTags.map((tag) => tag.name.toLowerCase()))
  const missingTags = DEFAULT_CLIENT_TAGS.filter(
    (tag) => !existingNames.has(tag.name.toLowerCase()),
  )

  if (missingTags.length === 0) return existingTags

  const { error } = await supabase.from('client_tags').insert(
    missingTags.map((tag) => ({
      studio_id: studioId,
      name: tag.name,
      color: tag.color,
      icon: tag.icon,
    })),
  )

  if (error && error.code !== '23505') {
    return existingTags
  }

  const { data } = await supabase
    .from('client_tags')
    .select('id, name, color, icon')
    .eq('studio_id', studioId)
