      last_visit_at: totalSessions > 0 ? faker.date.recent({ days: 90 }).toISOString() : null,
      consent_minor: false,
      preferred_contact: faker.helpers.arrayElement(['email', 'sms', 'phone'] as const),
      referral_source: faker.helpers.maybe(() => faker.person.firstName(), { probability: 0.3 }) ?? null,
      lifetime_value_cents: ltv,
      avg_session_value_cents: totalSessions > 0 ? Math.floor(ltv / totalSessions) : 0,
      no_show_count: faker.number.int({ min: 0, max: 2 }),
      cancellation_count: faker.number.int({ min: 0, max: 3 }),
      loyalty_points: faker.number.int({ min: 0, max: 500 }),
      instagram_handle: faker.helpers.maybe(() => `${first.toLowerCase()}.${last.toLowerCase()}`, { probability: 0.6 }) ?? null,
      is_banned: false,
      pronouns: faker.helpers.arrayElement(['she/her', 'he/him', 'they/them', null]),
    }
  })
  const { error: cErr } = await sb.from('clients').upsert(clientRows, { onConflict: 'id' })
  if (cErr) throw new Error(`[clients] clients upsert: ${cErr.message}`)
  log.module('clients', clientRows.length, 'clients')
  ctx.clientIds = clientRows.map((r) => r.id)

  // 3. Client notes — 1–2 per client, mixed categories
  const noteCategories = ['general', 'medical', 'allergies', 'preferences', 'artist_notes'] as const
  const noteRows: Array<{ id: string; studio_id: string; client_id: string; category: typeof noteCategories[number]; body: string; is_pinned: boolean; author_id: string }> = []
  clientRows.slice(0, 28).forEach((c, i) => {
    noteRows.push({
      id: detId('client_note', `${c.id}:1`),
      studio_id: ctx.studioId,
      client_id: c.id,
      category: noteCategories[i % noteCategories.length]!,
      body: faker.lorem.sentence({ min: 8, max: 15 }),
      is_pinned: i % 7 === 0,
      author_id: DEMO_USERS.owner.id,
    })
    if (i % 3 === 0) {
      noteRows.push({
        id: detId('client_note', `${c.id}:2`),
        studio_id: ctx.studioId,
        client_id: c.id,
        category: 'artist_notes',
        body: `Prefers ${faker.helpers.arrayElement(['morning', 'evening'])} sessions. ${faker.helpers.arrayElement(['Listens to lo-fi', 'Brings headphones', 'Chatty during outlining'])}.`,
        is_pinned: false,
        author_id: DEMO_USERS.artist1.id,
      })
    }
  })
  const { error: nErr } = await sb.from('client_notes').upsert(noteRows, { onConflict: 'id' })
  if (nErr) throw new Error(`[clients] client_notes upsert: ${nErr.message}`)
  log.module('clients', noteRows.length, 'client_notes')

  // 4. Client files — ID + medical form for some
  const fileRows: Array<{ id: string; studio_id: string; client_id: string; storage_path: string; file_name: string; mime_type: string; size_bytes: number; kind: 'id' | 'medical' | 'waiver' | 'health_form' | 'other'; uploaded_by: string }> = []
  clientRows.slice(0, 12).forEach((c) => {
    fileRows.push({
      id: detId('client_file', `${c.id}:id`),
      studio_id: ctx.studioId,
      client_id: c.id,
      storage_path: `client-files/demo/${c.id}/id.jpg`,
      file_name: 'drivers-license.jpg',
      mime_type: 'image/jpeg',
      size_bytes: 154_320,
      kind: 'id',
      uploaded_by: DEMO_USERS.recept1.id,
    })
  })
  const { error: fErr } = await sb.from('client_files').upsert(fileRows, { onConflict: 'id' })
  if (fErr) throw new Error(`[clients] client_files upsert: ${fErr.message}`)
  log.module('clients', fileRows.length, 'client_files')

  // 5. Client consent preferences — mostly opted-in to marketing
  const prefRows = clientRows.map((c, i) => ({
    id: detId('client_consent_prefs', c.id),
    studio_id: ctx.studioId,
    client_id: c.id,
    marketing_email: i % 4 !== 3,
    marketing_sms: i % 3 !== 2,
    transactional_only: false,
    photo_use_portfolio: i % 5 !== 0,
    photo_use_social: i % 7 !== 0,
    data_retention_years: 7,
    consent_version: 1,
    consented_at: new Date(Date.now() - faker.number.int({ min: 5, max: 400 }) * 86400_000).toISOString(),
  }))
  const { error: pErr } = await sb.from('client_consent_preferences').upsert(prefRows, { onConflict: 'id' })
  if (pErr) throw new Error(`[clients] client_consent_preferences upsert: ${pErr.message}`)
  log.module('clients', prefRows.length, 'client_consent_preferences')

  // 6. Waitlist entries
  const waitlistRows = Array.from({ length: 5 }, (_, i) => {
    const c = clientRows[i]!
    const artistId = ctx.artistIds[i % ctx.artistIds.length]!
    const svcId = ctx.serviceIds[i % ctx.serviceIds.length]!
    return {
      id: detId('waitlist', `${i}`),
      studio_id: ctx.studioId,
      client_id: c.id,
      service_id: svcId,
      artist_id: artistId,
      preferred_dates: null,
      preferred_days_of_week: [5, 6],
      notes: 'Weekend only please',
      status: 'active' as const,
    }
  })
  const { error: wErr } = await sb.from('waitlist_entries').upsert(waitlistRows, { onConflict: 'id' })
  if (wErr) throw new Error(`[clients] waitlist_entries upsert: ${wErr.message}`)
  log.module('clients', waitlistRows.length, 'waitlist_entries')
}

