 *   1. Find boldteq@gmail.com in auth.users (must exist — sign up if needed first)
 *   2. Upsert profile row (platform_admin = true)
 *   3. Upsert studio_members as role=owner on DEMO_STUDIO_ID
 *   4. Set the demo studio's active_studio cookie bias by ensuring this membership
 *      sorts first via joined_at = oldest date so getActiveStudio() picks it first
 *   5. Report state
 *
 * Usage:
 *   pnpm tsx --env-file=.env.local scripts/seed/demo/migrate-to-boldteq.ts
 */
import { adminClient } from './client'
import { DEMO_STUDIO_ID } from './constants'
import { detId } from './rng'
import { log } from './log'

const TARGET_EMAIL = 'yash@boldteq.com'

async function main(): Promise<void> {
  const sb = adminClient()
  log.header(`Migrating demo studio → ${TARGET_EMAIL}`)
  log.info(`Studio id: ${DEMO_STUDIO_ID}`)

  // 1. Find auth user
  const { data: listed, error: listErr } = await sb.auth.admin.listUsers({ page: 1, perPage: 500 })
  if (listErr) throw new Error(`listUsers: ${listErr.message}`)
  const user = listed.users.find((u) => u.email?.toLowerCase() === TARGET_EMAIL)
  if (!user) {
    throw new Error(
      `${TARGET_EMAIL} not found in auth.users. Sign up at /signup first, then re-run this script.`,
    )
  }
  log.ok(`Found user id ${user.id}`)

  // 2. Profile row — ensure exists, promote to platform admin so /admin works
  const { error: profErr } = await sb.from('profiles').upsert(
    {
      id: user.id,
      email: TARGET_EMAIL,
      full_name: user.user_metadata?.full_name ?? 'Boldteq',
      is_platform_admin: true,
    },
    { onConflict: 'id' },
  )
  if (profErr) throw new Error(`profiles upsert: ${profErr.message}`)
  log.ok('profile upserted with platform_admin=true')

  // 3. Studio member as owner — force joined_at way in the past so
  //    getActiveStudio() picks this studio first (ordered by created_at ASC)
  const joinedAt = new Date('2020-01-01T00:00:00Z').toISOString()
  const memberId = detId('studio_member', TARGET_EMAIL)
  const { error: memErr } = await sb.from('studio_members').upsert(
    {
      id: memberId,
      studio_id: DEMO_STUDIO_ID,
      user_id: user.id,
      role: 'owner',
      joined_at: joinedAt,
      last_active_at: new Date().toISOString(),
    },
    { onConflict: 'id' },
  )
  if (memErr) {
    // Fallback: maybe unique (studio_id, user_id). Update by that.
    const { error: upErr } = await sb
      .from('studio_members')
      .update({ role: 'owner', joined_at: joinedAt })
      .eq('studio_id', DEMO_STUDIO_ID)
      .eq('user_id', user.id)
    if (upErr) throw new Error(`studio_members upsert+update: ${memErr.message} / ${upErr.message}`)
  }
  log.ok(`studio_members: ${TARGET_EMAIL} → owner on demo studio`)

  // 4. Summary report
  const { count: memberCount } = await sb
    .from('studio_members')
    .select('*', { count: 'exact', head: true })
    .eq('studio_id', DEMO_STUDIO_ID)
  const { count: bookingCount } = await sb
    .from('bookings')
    .select('*', { count: 'exact', head: true })
    .eq('studio_id', DEMO_STUDIO_ID)
  const { count: clientCount } = await sb
    .from('clients')
    .select('*', { count: 'exact', head: true })
    .eq('studio_id', DEMO_STUDIO_ID)

  log.header('Done')
  log.info(`studio_members: ${memberCount ?? '?'}`)
  log.info(`bookings: ${bookingCount ?? '?'}`)
  log.info(`clients: ${clientCount ?? '?'}`)
  log.ok(`Log in as ${TARGET_EMAIL} with your existing password.`)
  log.info('If /dashboard still empty: clear the inkos_active_studio cookie and reload.')
}

main().catch((err) => {
  log.err(err instanceof Error ? err.stack ?? err.message : String(err))
  process.exit(1)
})

