  const { error: delStudioErr } = await sb.from('studios').delete().eq('id', DEMO_STUDIO_ID)
  if (delStudioErr) log.warn(`could not delete demo studio: ${delStudioErr.message}`)
  else log.ok('demo studio shell deleted')

