/**
 * Full data migration: move every row scoped to DEMO_STUDIO_ID onto
 * yash@boldteq.com's primary studio, then delete the demo studio shell.
 *
 * Steps:
 *   1. Look up yash@boldteq.com auth user
 *   2. Find or pick their primary studio (most recent owner/admin membership)
 *      If none exists, rename the demo studio to be his and exit.
 *   3. UPDATE every studio-scoped table: SET studio_id = TARGET_STUDIO_ID WHERE studio_id = DEMO_STUDIO_ID
 *   4. Point studio_members rows that pointed at DEMO_STUDIO_ID to TARGET_STUDIO_ID
 *      (skip the demo owner/artists — they only exist on demo studio and shouldn't bleed into yash's studio;
 *       those accounts stay, but lose their membership — delete instead)
 *   5. Delete DEMO_STUDIO_ID from studios (cascades any leftover members)
 *   6. Delete the 7 demo auth users (owner@demo.inkos.test etc)
 *
 * Usage:
 *   pnpm db:seed:demo:migrate-to-boldteq
 */
import { adminClient, type AdminClient } from './client'
import { DEMO_STUDIO_ID, DEMO_USER_LIST } from './constants'
import { log } from './log'

const TARGET_EMAIL = 'yash@boldteq.com'

// Every table with studio_id — reparented in order (doesn't matter much since
// we're changing the same FK value across all of them).
const STUDIO_SCOPED_TABLES = [
  'usage_meters',
  'feature_flags',
  'system_announcements', // has no studio_id — skipped by tolerant update
  'domain_verifications',
  'subscriptions',
  'locations',
  'studio_ink_registry',
  'studio_members',
  'artists',
  'artist_schedules',
  'artist_goals',
  'artist_tax_info',
  'artist_portfolio_items',
  'artist_blocked_dates',
  'location_assignments',
  'guest_artist_engagements',
  'services',
  'service_artists', // no studio_id either — skipped
  'style_tags',
  'booking_page_settings',
  'consent_form_templates',
  'consent_auto_send_rules',
  'consent_kiosk_sessions',
  'consent_form_submissions',
  'consent_form_requests',
  'message_templates',
  'client_tags',
  'clients',
  'client_notes',
  'client_files',
  'client_consent_preferences',
  'waitlist_entries',
  'projects',
  'project_deposit_transactions', // no studio_id — skipped, owned by project_id cascade
  'bookings',
  'booking_photos',
  'booking_participants',
  'project_activity_log',
  'project_references',
  'project_progress_photos',
  'payments',
  'invoices',
  'refund_requests',
  'commission_rules',
  'commission_records',
  'commission_adjustments',
  'commission_disputes',
  'payroll_runs',
  'payroll_artist_summary',
  'payroll_payment_batches',
  'tax_forms',
  'suppliers',
  'inventory_items',
  'inventory_movements',
  'stock_alerts',
  'purchase_orders',
  'purchase_order_lines',
  'reach_ink_records',
  'ai_design_templates',
  'ai_design_requests',
  'ai_design_outputs',
  'ai_usage_log',
  'marketing_campaigns',
  'referral_codes',
  'referral_redemptions',
  'flash_events',
  'conversations',
  'client_communications',
  'auto_reply_rules',
  'missed_calls',
  'inbox_assignments',
  'audit_log',
  'team_audit_log',
  'external_calendar_syncs',
  'user_pinned_items',
] as const

async function updateTable(sb: AdminClient, table: string, fromId: string, toId: string): Promise<number> {
  const { data, error } = await (sb.from(table as never) as unknown as {
    update: (v: { studio_id: string }) => {
      eq: (c: string, v: string) => {
        select: (s: string) => Promise<{ data: unknown[] | null; error: { message: string; code?: string } | null }>
      }
    }
  })
    .update({ studio_id: toId })
    .eq('studio_id', fromId)
    .select('*')
  if (error) {
    if (/column "studio_id" does not exist/i.test(error.message) ||
        /Could not find the 'studio_id' column/i.test(error.message) ||
        /Could not find the table/i.test(error.message)) {
      return -1 // table missing or has no studio_id — skip silently
    }
    throw new Error(`${table} update: ${error.message}`)
  }
  return data?.length ?? 0
}

async function main(): Promise<void> {
  const sb = adminClient()
  log.header(`Migrating demo → ${TARGET_EMAIL}`)
  log.info(`Source studio: ${DEMO_STUDIO_ID}`)

  // 1. Find target auth user
  const { data: listed } = await sb.auth.admin.listUsers({ page: 1, perPage: 500 })
  const user = listed.users.find((u) => u.email?.toLowerCase() === TARGET_EMAIL)
  if (!user) throw new Error(`${TARGET_EMAIL} not found in auth.users. Sign up first.`)
  log.ok(`Found user id ${user.id}`)

  // 2. Find target studio — pick the user's oldest membership, excluding demo
  const { data: memberships } = await sb
    .from('studio_members')
    .select('studio_id, role, joined_at')
    .eq('user_id', user.id)
    .neq('studio_id', DEMO_STUDIO_ID)
    .order('joined_at', { ascending: true })
  const targetMembership = memberships?.find((m) => m.role === 'owner' || m.role === 'admin') ?? memberships?.[0]

  let targetStudioId: string
  if (targetMembership) {
    targetStudioId = targetMembership.studio_id
    log.ok(`Target studio: ${targetStudioId} (existing)`)
  } else {
    // No existing studio — simplest path: rename demo studio to be yash's
    log.warn(`${TARGET_EMAIL} has no existing studio. Renaming demo studio instead of migrating.`)
    const { error: renameErr } = await sb
      .from('studios')
      .update({
        name: 'Inkhaus Studio',
        slug: `inkhaus-${user.id.slice(0, 6)}`,
      })
      .eq('id', DEMO_STUDIO_ID)
    if (renameErr) throw new Error(`rename studios: ${renameErr.message}`)

    // Ensure yash is owner
    const { error: memErr } = await sb.from('studio_members').upsert(
      {
        studio_id: DEMO_STUDIO_ID,
        user_id: user.id,
        role: 'owner',
        joined_at: new Date('2020-01-01T00:00:00Z').toISOString(),
      },
      { onConflict: 'studio_id,user_id' },
    )
    if (memErr) {
      // Fallback without onConflict spec
      await sb.from('studio_members').insert({
        studio_id: DEMO_STUDIO_ID,
        user_id: user.id,
        role: 'owner',
        joined_at: new Date('2020-01-01T00:00:00Z').toISOString(),
      })
    }
    await sb.from('profiles').upsert(
      { id: user.id, email: TARGET_EMAIL, is_platform_admin: true, full_name: 'Yash Baldha' },
      { onConflict: 'id' },
    )
    log.ok('Demo studio renamed + yash set as owner')
    log.header('Done')
    log.ok(`Log in as ${TARGET_EMAIL}. Clear inkos_active_studio cookie if dashboard empty.`)
    return
  }

  // 3a. Clear target studio of existing rows so reparent doesn't hit unique constraints.
  //     Order matters: children before parents.
  log.header('Clearing target studio (existing rows will be replaced)')
  const CLEAR_ORDER = [...STUDIO_SCOPED_TABLES].reverse()
  for (const t of CLEAR_ORDER) {
    const { error } = await (sb.from(t as never) as unknown as {
      delete: () => { eq: (c: string, v: string) => Promise<{ error: { message: string } | null }> }
    })
      .delete()
      .eq('studio_id', targetStudioId)
    if (error && !/column "studio_id" does not exist/i.test(error.message) && !/Could not find/i.test(error.message)) {
      log.warn(`clear ${t}: ${error.message}`)
    }
  }
  log.ok('target studio cleared')

  // 3b. Unlock paid payroll_runs so we can change studio_id (trigger blocks updates otherwise)
  await (sb.from('payroll_runs' as never) as unknown as {
    update: (v: { status: string }) => { eq: (c: string, v: string) => Promise<{ error: unknown }> }
  })
    .update({ status: 'draft' })
    .eq('studio_id', DEMO_STUDIO_ID)

  // 3c. Reparent every studio-scoped row
  log.header('Reparenting rows')
  const results: Array<{ table: string; count: number }> = []
  for (const t of STUDIO_SCOPED_TABLES) {
    const count = await updateTable(sb, t, DEMO_STUDIO_ID, targetStudioId)
    if (count >= 0) {
      results.push({ table: t, count })
      if (count > 0) log.ok(`${t}: ${count}`)
    }
  }

  // 3d. Restore payroll_runs to paid status on target studio
  await (sb.from('payroll_runs' as never) as unknown as {
    update: (v: { status: string }) => { eq: (c: string, v: string) => Promise<{ error: unknown }> }
  })
    .update({ status: 'paid' })
    .eq('studio_id', targetStudioId)

  // 4. Drop any leftover demo-user memberships on the target studio
  //    (demo auth users don't need to be yash's teammates)
  const demoUserIds = DEMO_USER_LIST.map((u) => u.id)
  await sb
    .from('studio_members')
    .delete()
    .eq('studio_id', targetStudioId)
    .in('user_id', demoUserIds)

  // 5. Delete demo studio shell
  const { error: delStudioErr } = await sb.from('studios').delete().eq('id', DEMO_STUDIO_ID)
  if (delStudioErr) log.warn(`could not delete demo studio: ${delStudioErr.message}`)
  else log.ok('demo studio shell deleted')

  // 6. Delete demo auth users
  for (const u of DEMO_USER_LIST) {
    const { error } = await sb.auth.admin.deleteUser(u.id)
    if (error && !/not.*found/i.test(error.message)) {
      log.warn(`auth user ${u.email}: ${error.message}`)
    }
  }
  log.ok('demo auth users deleted')

  // 7. Ensure yash profile platform-admin
  await sb
    .from('profiles')
    .upsert({ id: user.id, email: TARGET_EMAIL, is_platform_admin: true }, { onConflict: 'id' })

  log.header('Done')
  const total = results.reduce((a, r) => a + r.count, 0)
  log.info(`Total rows reparented: ${total}`)
  log.info(`Target studio: ${targetStudioId}`)
  log.ok(`Log in as ${TARGET_EMAIL}. Clear inkos_active_studio cookie if needed.`)
