/**
 * Make yash@boldteq.com the owner of the fully-seeded demo studio.
 *
 * Instead of copying data (which collides with unique constraints + paid-payroll
 * triggers), we rename the demo studio to yash's brand and attach him as the
 * primary owner. All 55+ tables of demo data stay put under one studio id.
 *
 * Steps:
 *   1. Find yash@boldteq.com in auth.users
 *   2. Delete any other studio(s) he currently owns (empty shells from signup)
 *   3. Rename demo studio → Boldteq InkOS brand
 *   4. Upsert yash as studio_member(role=owner) with joined_at=2020 so active-studio
 *      resolver picks it first
 *   5. Platform-admin flag on profile
 *
 * Usage: pnpm db:seed:demo:migrate-to-boldteq
 */
import { adminClient } from './client'
import { DEMO_STUDIO_ID } from './constants'
import { log } from './log'

const TARGET_EMAIL = 'yash@boldteq.com'
const TARGET_STUDIO_NAME = 'Boldteq InkOS'
const TARGET_STUDIO_SLUG = 'boldteq-inkos'

async function main(): Promise<void> {
  const sb = adminClient()
  log.header(`Migrating demo studio → ${TARGET_EMAIL}`)
  log.info(`Studio: ${DEMO_STUDIO_ID}`)

  // 1. Find auth user
  const { data: listed } = await sb.auth.admin.listUsers({ page: 1, perPage: 500 })
  const user = listed.users.find((u) => u.email?.toLowerCase() === TARGET_EMAIL)
  if (!user) throw new Error(`${TARGET_EMAIL} not found in auth.users. Sign up first.`)
  log.ok(`user id ${user.id}`)

  // 2. Delete any other studios yash owns (except the demo studio itself)
  const { data: otherMemberships } = await sb
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .neq('studio_id', DEMO_STUDIO_ID)
  const owned = (otherMemberships ?? []).filter((m) => m.role === 'owner')
  for (const m of owned) {
    // Unlock paid payroll, then delete (cascade handles scoped rows)
    await sb.from('payroll_payment_batches').delete().eq('studio_id', m.studio_id)
    await sb.from('payroll_artist_summary').delete().eq('studio_id', m.studio_id)
    await sb.from('payroll_runs').delete().eq('studio_id', m.studio_id)
    const { error } = await sb.from('studios').delete().eq('id', m.studio_id)
    if (error) log.warn(`could not delete ${m.studio_id}: ${error.message}`)
    else log.ok(`deleted leftover studio ${m.studio_id}`)
  }

  // 3. Rename demo studio to yash's brand
  const { error: renErr } = await sb
    .from('studios')
    .update({
      name: TARGET_STUDIO_NAME,
      slug: `${TARGET_STUDIO_SLUG}-${user.id.slice(0, 6)}`,
    })
    .eq('id', DEMO_STUDIO_ID)
  if (renErr) throw new Error(`rename: ${renErr.message}`)
  log.ok(`studio renamed → ${TARGET_STUDIO_NAME}`)

  // 4. Attach yash as owner. joined_at=2020 so active-studio resolver picks it first.
  //    Use delete-then-insert to avoid onConflict guesswork.
  await sb.from('studio_members').delete().eq('studio_id', DEMO_STUDIO_ID).eq('user_id', user.id)
  const { error: memErr } = await sb.from('studio_members').insert({
    studio_id: DEMO_STUDIO_ID,
    user_id: user.id,
    role: 'owner',
    joined_at: new Date('2020-01-01T00:00:00Z').toISOString(),
    last_active_at: new Date().toISOString(),
  })
  if (memErr) throw new Error(`studio_members: ${memErr.message}`)
  log.ok(`yash attached as owner`)

  // 5. Platform admin flag so /admin accessible
  await sb.from('profiles').upsert(
    {
      id: user.id,
      email: TARGET_EMAIL,
      full_name: user.user_metadata?.full_name ?? 'Yash Baldha',
      is_platform_admin: true,
    },
    { onConflict: 'id' },
  )
  log.ok('profile platform_admin=true')

  // 6. Report
  const { count: mem } = await sb.from('studio_members').select('*', { count: 'exact', head: true }).eq('studio_id', DEMO_STUDIO_ID)
  const { count: bk } = await sb.from('bookings').select('*', { count: 'exact', head: true }).eq('studio_id', DEMO_STUDIO_ID)
  const { count: cl } = await sb.from('clients').select('*', { count: 'exact', head: true }).eq('studio_id', DEMO_STUDIO_ID)
  const { count: py } = await sb.from('payments').select('*', { count: 'exact', head: true }).eq('studio_id', DEMO_STUDIO_ID)

  log.header('Done')
  log.info(`studio_members: ${mem} · bookings: ${bk} · clients: ${cl} · payments: ${py}`)
  log.ok(`Log in as ${TARGET_EMAIL}. Clear inkos_active_studio cookie if dashboard empty.`)
}

main().catch((err) => {
  log.err(err instanceof Error ? err.stack ?? err.message : String(err))
  process.exit(1)
})

