for (const c of CHECKS) {
  let query = sb.from(c.table as never).select('*', { count: 'exact', head: true })
  if (c.filter) {
    for (const [k, v] of Object.entries(c.filter)) {
      query = (query as never as { eq: (col: string, val: unknown) => typeof query }).eq(k, v)
    }
  } else {
    query = (query as never as { eq: (col: string, val: unknown) => typeof query }).eq('studio_id', DEMO_STUDIO_ID)
  }
  const { count, error } = await query
  const actual = count ?? 0
  const ok = !error && actual >= c.min
  if (!ok) failed++
  results.push({ name: c.table, count: error ? -1 : actual, min: c.min, ok })
}

